<?php
namespace App\Domain\AI\Runtime\Data;
final readonly class ModelResponseData{public function __construct(public string$providerResponseId,public string$model,public string$status,public array$structuredOutput,public int$inputUnits,public int$cachedInputUnits,public int$outputUnits,public int$totalUnits,public int$latencyMilliseconds){foreach([$inputUnits,$cachedInputUnits,$outputUnits,$totalUnits,$latencyMilliseconds]as$v)if($v<0)throw new \InvalidArgumentException('Invalid model response metrics.');if($providerResponseId===''||preg_match('/[\x00-\x20\x7F]/',$providerResponseId)||$model===''||$status!=='completed'||$cachedInputUnits>$inputUnits||$totalUnits<$inputUnits+$outputUnits)throw new \App\Domain\AI\Runtime\Exceptions\InvalidModelResponseException('Invalid model response metadata.');}}
